import React, { useState } from 'react';
import { useLocation } from 'react-router-dom';
import { Box, Typography, Paper, CircularProgress, Alert, Grid, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Button, Dialog, DialogTitle, DialogContent, DialogContentText, DialogActions } from '@mui/material';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';
import { AnalyticsData, User, UserActivity } from '../utils/database';
import { PageHeader } from './PageHeader';
import { theme } from '../theme/theme';

interface SummaryPageProps {
    data: AnalyticsData | null;
    loading: boolean;
    error: string | null;
    users: User[];
}

const SummaryPage: React.FC<SummaryPageProps> = ({ data, loading, error, users }) => {
    const location = useLocation();
    const isSnapshotMode = location.pathname.startsWith('/snapshot');
    const [helpOpen, setHelpOpen] = useState(false);

    const handleHelpOpen = () => {
        setHelpOpen(true);
    };

    const handleHelpClose = () => {
        setHelpOpen(false);
    };
    function renderTopUsersTable(title: string, data: UserActivity[], countLabel: string) {
    if (!data || data.length === 0) return null;

    return (
      <Box sx={{ mt: 4 }}>
        <Typography variant="h6" gutterBottom sx={{ fontSize: { xs: '1rem', md: '1.25rem' } }}>
          {title}
        </Typography>
        <Paper sx={{ p: 2 }}>
          <TableContainer sx={{ maxHeight: { xs: 400, md: 'none' }, overflowX: 'auto' }}>
            <Table stickyHeader size="small" sx={{ minWidth: { xs: 300, md: 400 } }}>
              <TableHead>
                <TableRow>
                  <TableCell sx={{ fontWeight: 'bold', fontSize: { xs: '0.75rem', md: '0.875rem' } }}>User</TableCell>
                  <TableCell align="right" sx={{ fontWeight: 'bold', fontSize: { xs: '0.75rem', md: '0.875rem' } }}>{countLabel}</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {data.map((user: UserActivity) => (
                  <TableRow key={user.name}>
                    <TableCell component="th" scope="row" sx={{ fontSize: { xs: '0.75rem', md: '0.875rem' } }}>
                      {user.name}
                    </TableCell>
                    <TableCell align="right" sx={{ fontSize: { xs: '0.75rem', md: '0.875rem' } }}>{user.count}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      </Box>
    );
  }
    // Always use the full analytics data, not filtered by selection
    const renderKpiCard = (title: string, value: string | number) => (
        <Grid item xs={12} sm={4}>
            <Paper sx={{ p: 2, textAlign: 'center', background: 'linear-gradient(135deg, #f4f7fa 70%, #e3ecf7 100%)', boxShadow: 3, borderRadius: 3, border: '1px solid #d6e0ef' }}>
                <Typography variant="h4" component="div">{value}</Typography>
                <Typography variant="body1" color="text.secondary">{title}</Typography>
            </Paper>
        </Grid>
    );

    return (
        <Box sx={{ p: { xs: 1, md: 3 } }}>
            {data && (
                <PageHeader 
                    title={isSnapshotMode ? "Signal Snapshot - Units 2025" : "Signal Snapshot Dashboard"}
                    subtitle="Welcome to your Signal Snapshot! Explore different layers of your Signal ecosystem."
                />
            )}
            {loading && (
                <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: 200 }}>
                    <CircularProgress />
                </Box>
            )}
            {error && (
                <Alert severity="error" sx={{ mb: 2 }}>
                    {error}
                </Alert>
            )}
            {!loading && !error && data ? (
                <>
                    <Grid container spacing={3} sx={{ mb: 4 }}>
                        {renderKpiCard('Total Messages', data.kpis.total_messages)}
                        {renderKpiCard('Total Conversations', data.kpis.total_conversations)}
                        {renderKpiCard('Total Users', users.length)}
                    </Grid>
                    <Paper sx={{ p: { xs: 2, md: 3 }, mt: 2 }}>
                        <Typography variant="h6" gutterBottom sx={{ fontSize: { xs: '1rem', md: '1.25rem' } }}>
                            Top Conversations by Message Count
                        </Typography>
                        {data.top_conversations && data.top_conversations.length > 0 ? (
                            <TableContainer sx={{ maxHeight: { xs: 400, md: 'none' }, overflowX: 'auto' }}>
                                <Table size="small" sx={{ minWidth: { xs: 300, md: 400 } }}>
                                    <TableHead>
                                        <TableRow>
                                            <TableCell sx={{ fontWeight: 'bold', fontSize: { xs: '0.75rem', md: '0.875rem' } }}>Conversation</TableCell>
                                            <TableCell align="right" sx={{ fontWeight: 'bold', fontSize: { xs: '0.75rem', md: '0.875rem' } }}>Messages</TableCell>
                                        </TableRow>
                                    </TableHead>
                                    <TableBody>
                                        {data.top_conversations.map((convo) => (
                                            <TableRow key={convo.name}>
                                                <TableCell sx={{ fontSize: { xs: '0.75rem', md: '0.875rem' } }}>{convo.name}</TableCell>
                                                <TableCell align="right" sx={{ fontSize: { xs: '0.75rem', md: '0.875rem' } }}>{convo.count}</TableCell>
                                            </TableRow>
                                        ))}
                                    </TableBody>
                                </Table>
                            </TableContainer>
                        ) : (
                            <Typography variant="body2" color="text.secondary">No data</Typography>
                        )}
                    </Paper>
                    <Grid container spacing={3} sx={{ mt: 0 }}>
                        <Grid item xs={12} md={6}>
                            {renderTopUsersTable(
                                'Top Users by Message Count',
                                data.topUsersByMessageCount,
                                'Messages Sent'
                            )}
                        </Grid>
                        <Grid item xs={12} md={6}>
                            {renderTopUsersTable(
                                'Top Users by Reaction Count',
                                data.topUsersByReactionCount,
                                'Reactions Given'
                            )}
                        </Grid>
                    </Grid>
                </>
            ) : null}
        </Box>
    );
};

export default SummaryPage;
